<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';
import {assetUrl} from './asset-url.js';
const appBase=import.meta.env.BASE_URL;
const imageUrl=value=>assetUrl(value,appBase);
import RuleGroup from './RuleGroup.vue';
import ShipSpecs from './ShipSpecs.vue';
import CrewValue from './CrewValue.vue';
import CardDeflection from './CardDeflection.vue';
import ShipRoleTags from './ShipRoleTags.vue';
import AcquisitionFilter from './AcquisitionFilter.vue';
import {acquisitionOptions,acquisitionMethods,matchesAcquisition,acquisitionNote} from './acquisition.js';
const acquisition=ref([]);
const acquisitionById=computed(()=>Object.fromEntries(ships.value.map(s=>[s.id,acquisitionMethods(s)])));
const acquisitionCounts=computed(()=>Object.fromEntries(acquisitionOptions.map(o=>[o.value,ships.value.filter(s=>acquisitionById.value[s.id].includes(o.value)).length])));
import FieldExplorer from './FieldExplorer.vue';
import {migrateComparison,fieldSearchText} from './catalog-quality.js';
import FieldScope from './FieldScope.vue';
import ComparisonFieldPicker from './ComparisonFieldPicker.vue';
import FieldValue from './FieldValue.vue';
import PvpComparison from './PvpComparison.vue';
const comparisonMode=ref('specs');
import {fieldVisible} from './field-presentation.js';
import {matchGroup,compareValue,different,isMissing,csv,validateGroup} from './engine.js';
const catalog=ref(null),error=ref(''),query=ref(''),manufacturers=ref([]),status=ref(''),kind=ref('all'),minCargo=ref(''),maxCrew=ref(''),maxPrice=ref(''),sort=ref('name'),direction=ref('asc'),view=ref('grid'),page=ref(1),builder=ref(false),modal=ref(''),detail=ref(null),mobileFilters=ref(false),scope=ref('standard'),compareSearch=ref(''),diffOnly=ref(true),notice=ref(''),presetName=ref(''),saved=ref([]),selected=ref([]),root=ref({id:'root',mode:'and',children:[]});
const ships=computed(()=>catalog.value?.ships||[]),fields=computed(()=>catalog.value?.fields||[]),fieldMap=computed(()=>Object.fromEntries(fields.value.map(f=>[f.key,f])));
const mainKeys=['manufacturer','focus','status','size','ground','crewMin','crewMax','cargo','length','beam','height','mass','scm','speed','pitch','yaw','roll','hull','hydrogen','quantum','price','pledge','inGame','source','gunCount','gunMaxSize','missileCount','shieldCount','shieldTotal','armorTotal'];
const archivedFields=computed(()=>catalog.value?.archivedFields||[]);
const compatibleFields=computed(()=>[...fields.value,...archivedFields.value]);
const comparisonDefaults=computed(()=>migrateComparison(mainKeys,fields.value,archivedFields.value));
const manufacturerOptions=computed(()=>[...new Set(ships.value.map(s=>s.values.manufacturer))].sort());
const statuses=computed(()=>[...new Set(ships.value.map(s=>s.values.status))].sort());
const labels={'flight-ready':'В игре','in-concept':'Концепт','in-production':'В производстве',small:'Малый',medium:'Средний',large:'Большой',capital:'Капитальный',snub:'Снаб',vehicle:'Техника',and:'И',or:'ИЛИ'};
const fmt=(v,key)=>{if(isMissing(v))return '—';if(Array.isArray(v))return [...new Set(v)].map(x=>fmt(x,key)).join(' · ');if(typeof v==='boolean')return v?'Да':'Нет';if(typeof v==='number')return v.toLocaleString('ru-RU',{maximumFractionDigits:3});return labels[v]||String(v)};
const compact=v=>isMissing(v)?'—':Number(v)>=1e6?(v/1e6).toLocaleString('ru',{maximumFractionDigits:2})+' млн':fmt(v);
function quickMatch(s){let v=s.values;return (!query.value||(s.name+' '+v.manufacturer+' '+v.focus).toLowerCase().includes(query.value.toLowerCase()))&&(!manufacturers.value.length||manufacturers.value.includes(v.manufacturer))&&(!status.value||v.status===status.value)&&matchesAcquisition(acquisitionById.value[s.id],acquisition.value)&&(kind.value==='all'||(kind.value==='ship'?v.ground===false:v.ground===true))&&(minCargo.value===''||!isMissing(v.cargo)&&v.cargo>=Number(minCargo.value))&&(maxCrew.value===''||!isMissing(v.crewMin)&&v.crewMin<=Number(maxCrew.value))&&(maxPrice.value===''||!isMissing(v.price)&&v.price<=Number(maxPrice.value))}
const quickResults=computed(()=>ships.value.filter(quickMatch));
const results=computed(()=>quickResults.value.filter(s=>matchGroup(s.values,root.value)).sort((a,b)=>compareValue(a.values[sort.value],b.values[sort.value],direction.value)));
const pageSize=24,totalPages=computed(()=>Math.max(1,Math.ceil(results.value.length/pageSize))),visible=computed(()=>results.value.slice((page.value-1)*pageSize,page.value*pageSize));
const selectedShips=computed(()=>selected.value.map(id=>ships.value.find(s=>s.id===id)).filter(Boolean));
const comparisonKeys=ref([...mainKeys]);
const comparisonKeySet=computed(()=>new Set(comparisonKeys.value));
const compareFields=computed(()=>fields.value.filter(f=>comparisonKeySet.value.has(f.key)&&(!compareSearch.value||fieldSearchText(f).includes(compareSearch.value.toLowerCase()))&&(!diffOnly.value||different(selectedShips.value,f.key))));

const ruleKeys=g=>g.children.flatMap(n=>n.children?ruleKeys(n):[n.field]);
const builderFields=computed(()=>{const used=new Set(ruleKeys(root.value));return [...fields.value.filter(f=>fieldVisible(f,scope.value)||used.has(f.key)),...archivedFields.value.filter(f=>used.has(f.key)).map(f=>({...f,label:f.label+' (архивное условие)',group:'Сохранённые условия'}))]});
const countRules=g=>g.children.reduce((n,c)=>n+(c.children?countRules(c):1),0);
const activeCount=computed(()=>countRules(root.value)+acquisition.value.length+manufacturers.value.length+Number(!!status.value)+Number(kind.value!=='all')+[minCargo.value,maxCrew.value,maxPrice.value].filter(x=>x!=='').length);
const snapshotDate=computed(()=>catalog.value?.meta.fetchedAt?new Date(catalog.value.meta.fetchedAt).toLocaleDateString('ru-RU',{timeZone:'Europe/Moscow'}):'—');
const coverage=computed(()=>fields.value.length);
const hero=computed(()=>ships.value.find(s=>s.name==='Zeus Mk II ES')||ships.value.find(s=>s.name==='Carrack'));
const statusNote=s=>`Статус из ${s.origins.status||'источника'} на ${catalog.value?.meta.fetchedAt||'дату снимка'}: ${s.values.status||'не указан'}. Это статус каталога, не проверка доступности в текущем LIVE и не наличие в продаже.`;
const sourceName=(s,key)=>s.origins[key]||(key.startsWith('fy.')||key.startsWith('game.')?'FleetYards':key.startsWith('rsi.')?'RSI':'');
function toast(s){notice.value=s;setTimeout(()=>{if(notice.value===s)notice.value=''},3500)}
function snapshot(){return {query:query.value,manufacturers:manufacturers.value,acquisition:acquisition.value,status:status.value,kind:kind.value,minCargo:minCargo.value,maxCrew:maxCrew.value,maxPrice:maxPrice.value,root:root.value,sort:sort.value,direction:direction.value,selected:selected.value,view:view.value}}
function restore(s){if(!s||!validateGroup(s.root,compatibleFields.value))throw Error('Некорректная воронка или неизвестные поля');query.value=typeof s.query==='string'?s.query:'';manufacturers.value=Array.isArray(s.manufacturers)?s.manufacturers.filter(x=>manufacturerOptions.value.includes(x)):[];acquisition.value=Array.isArray(s.acquisition)?[...new Set(s.acquisition.filter(x=>acquisitionOptions.some(o=>o.value===x)))]:[];status.value=statuses.value.includes(s.status)?s.status:'';kind.value=['all','ship','ground'].includes(s.kind)?s.kind:'all';minCargo.value=s.minCargo??'';maxCrew.value=s.maxCrew??'';maxPrice.value=s.maxPrice??'';root.value=JSON.parse(JSON.stringify(s.root));sort.value=fieldMap.value[s.sort]?s.sort:'name';direction.value=s.direction==='desc'?'desc':'asc';selected.value=Array.isArray(s.selected)?s.selected.filter(id=>ships.value.some(x=>x.id===id)):[];view.value=s.view==='table'?'table':'grid'}
function persist(){try{localStorage.setItem('atlas-state-v1',JSON.stringify(snapshot()))}catch{toast('Хранилище браузера недоступно — экспортируйте воронку')}}
function reset(){query.value='';manufacturers.value=[];acquisition.value=[];status.value='';kind.value='all';minCargo.value='';maxCrew.value='';maxPrice.value='';root.value={id:'root',mode:'and',children:[]};page.value=1}
function toggle(s){selected.value=selected.value.includes(s.id)?selected.value.filter(x=>x!==s.id):[...selected.value,s.id]}
function quickPreset(type){reset();if(type==='solo'){maxCrew.value=1;status.value='flight-ready';kind.value='ship'}if(type==='cargo'){minCargo.value=100;kind.value='ship'}if(type==='combat'){root.value.children=[{id:crypto.randomUUID(),field:'focus',op:'contains',value:'Fighter',unknown:'exclude'}];kind.value='ship'}if(type==='new'){root.value.children=[{id:crypto.randomUUID(),field:'added',op:'eq',value:'true',unknown:'exclude'}]}}
function savePreset(){const name=presetName.value.trim();if(!name)return;const data=JSON.parse(JSON.stringify(snapshot()));saved.value.push({id:crypto.randomUUID(),name,data});localStorage.setItem('atlas-presets-v1',JSON.stringify(saved.value));presetName.value='';toast('Воронка сохранена в этом браузере')}
function deletePreset(id){saved.value=saved.value.filter(x=>x.id!==id);localStorage.setItem('atlas-presets-v1',JSON.stringify(saved.value))}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportResults(){const ff=fields.value.filter(f=>!f.technical);download('atlas-ships.csv',csv([['Корабль',...ff.map(f=>f.label+' ['+f.key+']')],...results.value.map(s=>[s.name,...ff.map(f=>fmt(s.values[f.key],f.key))])]),'text/csv;charset=utf-8');toast('Экспортирована текущая выборка')}
async function importPreset(event){try{const file=event.target.files[0];if(!file)return;if(file.size>1e6)throw Error('Файл слишком большой');restore(JSON.parse(await file.text()));toast('Воронка загружена')}catch(e){toast(e.message)}event.target.value=''}
function share(){const url=new URL(location.href);url.hash='f='+encodeURIComponent(JSON.stringify(snapshot()));navigator.clipboard.writeText(url.toString()).then(()=>toast('Ссылка на воронку скопирована')).catch(()=>{modal.value='share';shareLink.value=url.toString()})}
const shareLink=ref('');
const reloadPage=()=>window.location.reload();
function showDetail(s){detail.value=s;modal.value='detail'}
function addField(f){root.value.children.push({id:crypto.randomUUID(),field:f.key,op:f.type==='number'?'gte':'eq',value:f.type==='boolean'?'true':'',unknown:'exclude',quantifier:'any'});modal.value='';builder.value=true;toast('Условие добавлено — задайте значение')}
function escape(e){if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!modal.value&&!builder.value){e.preventDefault();document.querySelector('[aria-label="Поиск корабля"]')?.focus()}if(e.key==='Escape'){modal.value='';builder.value=false;mobileFilters.value=false}}
onMounted(async()=>{window.addEventListener('keydown',escape);try{const r=await fetch(appBase+'data/catalog.json');if(!r.ok)throw Error('Не удалось загрузить каталог');catalog.value=await r.json();comparisonKeys.value=[...comparisonDefaults.value];try{const stored=JSON.parse(localStorage.getItem('atlas-comparison-fields-v1')||'null');if(Array.isArray(stored))comparisonKeys.value=migrateComparison(stored,fields.value,archivedFields.value)}catch{toast('Не удалось восстановить набор сравнения')}watch(comparisonKeys,keys=>{try{localStorage.setItem('atlas-comparison-fields-v1',JSON.stringify(keys))}catch{toast('Не удалось сохранить набор сравнения')}},{deep:true});try{saved.value=JSON.parse(localStorage.getItem('atlas-presets-v1')||'[]');const fromHash=location.hash.startsWith('#f=')?decodeURIComponent(location.hash.slice(3)):null;const s=fromHash||localStorage.getItem('atlas-state-v1');if(s)restore(JSON.parse(s))}catch{toast('Сохранённые параметры не удалось восстановить')}watch([query,manufacturers,acquisition,status,kind,minCargo,maxCrew,maxPrice,root,sort,direction],()=>{page.value=1},{deep:true});watch([query,manufacturers,acquisition,status,kind,minCargo,maxCrew,maxPrice,root,sort,direction,selected,view],persist,{deep:true})}catch(e){error.value=e.message}});
onUnmounted(()=>window.removeEventListener('keydown',escape));
watch([modal,builder],()=>{document.body.style.overflow=modal.value||builder.value?'hidden':''});
</script>

<template>
 <div class="app-shell">
  <header class="topbar"><a :href="appBase" class="brand" aria-label="ATLAS — главная"><span class="brand-icon">◈</span> ATLAS<span class="brand-sub">SHIP INTELLIGENCE</span></a><nav><button class="nav-item active" @click="modal='';builder=false">Каталог</button><button class="nav-item" @click="modal='compare'">Сравнение <span class="counter">{{selected.length}}</span></button><button class="nav-item" @click="modal='saved'">Мои воронки</button></nav><button class="source-indicator" @click="modal='sources'"><i></i> Данные · {{snapshotDate}} <span>↗</span></button></header>
  <div v-if="!catalog" class="loading"><span class="brand-icon">◈</span><h2>{{error||'Загружаем карту флота…'}}</h2><button v-if="error" @click="reloadPage">Повторить</button></div>
  <template v-else>
   <section class="hero"><div class="hero-grid"></div><img v-if="hero?.image" :src="imageUrl(hero.image)" class="hero-image" alt="Zeus Mk II ES"><div class="hero-copy"><div class="eyebrow"><span class="orange-line"></span> STAR CITIZEN / SHIP DATABASE</div><h1>Ваш корабль.<br><span>Ваши условия.</span></h1><p>От первого полёта до собственного флота.<br>Сужайте поиск. Сравнивайте. Выбирайте.</p><div class="hero-stats"><div><b>{{ships.length}}</b><span>моделей и изданий</span></div><div><b>{{coverage}}</b><span>полей характеристик</span></div><div><b>И / ИЛИ</b><span>гибкие воронки</span></div></div></div><div class="hero-caption" v-if="hero"><span>В КАТАЛОГЕ</span><b>{{hero.name}}</b><small>{{hero.values.manufacturer}} <span>↗</span></small></div></section>
   <main class="workspace"><aside class="sidebar" :class="{mobileOpen:mobileFilters}"><div class="sidebar-title"><h2>Фильтры <span>{{activeCount}}</span></h2><button class="text-button" @click="reset">Сбросить</button><button class="mobile-only icon-button" @click="mobileFilters=false" aria-label="Закрыть фильтры">×</button></div>
    <div class="filter-section"><label class="section-label">Тип техники</label><div class="segmented"><button v-for="[key,label] in [['all','Все'],['ship','Корабли'],['ground','Наземная']]" :key="key" :class="{selected:kind===key}" @click="kind=key">{{label}}</button></div></div>
    <div class="filter-section"><label class="section-label" for="status">Готовность</label><select id="status" v-model="status"><option value="">Любой статус</option><option v-for="s in statuses" :value="s" :key="s">{{fmt(s)}}</option></select></div>
    <AcquisitionFilter v-model="acquisition" :counts="acquisitionCounts" />
    <details class="filter-section" open><summary class="section-label">Производитель <span>{{manufacturers.length||'Все'}}</span></summary><div class="manufacturer-list"><label v-for="m in manufacturerOptions" :key="m" class="check-row"><input type="checkbox" :value="m" v-model="manufacturers"><span>{{m}}</span><small>{{ships.filter(s=>s.values.manufacturer===m).length}}</small></label></div></details>
    <div class="filter-section"><label for="cargo" class="section-label">Груз <span>SCU</span></label><div class="number-field"><span>от</span><input id="cargo" type="number" min="0" step="any" placeholder="Любой" v-model="minCargo"></div><div class="range-presets"><button v-for="n in [0,32,100,500]" :key="n" @click="minCargo=n">{{n}}+</button></div></div>
    <div class="filter-section"><label for="crew" class="section-label">Минимальный экипаж <span>чел.</span></label><div class="number-field"><span>до</span><input id="crew" type="number" min="0" placeholder="Любой" v-model="maxCrew"></div></div>
    <div class="filter-section"><label for="price" class="section-label">Цена в игре <span>aUEC</span></label><div class="number-field"><span>до</span><input id="price" type="number" min="0" placeholder="Без ограничений" v-model="maxPrice"></div><small class="muted">Пустое поле — без ограничения.<br>При заданном лимите неизвестные исключены.</small></div>
    <button class="all-fields-button" @click="modal='fields'">Все характеристики <span>↗</span></button><p class="sidebar-note">Габариты, скорость, корпус, топливо, компоненты, магазины и вложенные параметры.</p>
   </aside>
   <section class="catalog"><div class="catalog-top"><div><div class="eyebrow">КАТАЛОГ / {{String(results.length).padStart(3,'0')}}</div><h2>Найдите свой корабль</h2></div><button class="outline-button" @click="builder=true"><span>☷</span> Конструктор воронки <span v-if="countRules(root)">{{countRules(root)}}</span></button></div>
    <div class="search-row"><div class="search-box"><span>⌕</span><input v-model="query" placeholder="Название, производитель или назначение…" aria-label="Поиск корабля"><button v-if="query" class="icon-button" @click="query=''" aria-label="Очистить поиск">×</button><kbd>/</kbd></div><button class="mobile-only outline-button" @click="mobileFilters=true">Фильтры</button></div>
    <div class="quick-presets"><span>Быстрый старт</span><button @click="quickPreset('solo')">↗ Для одного</button><button @click="quickPreset('cargo')">▱ Грузовые 100+ SCU</button><button @click="quickPreset('combat')">⌖ Истребители</button><button @click="quickPreset('new')">＋ Дополнения RSI</button></div>
    <div v-if="activeCount" class="active-filters"><span>{{activeCount}} активных условий</span><button v-for="m in manufacturers" :key="m" @click="manufacturers=manufacturers.filter(x=>x!==m)">{{m}} ×</button><button v-for="o in acquisitionOptions.filter(o=>acquisition.includes(o.value))" :key="o.value" @click="acquisition=acquisition.filter(x=>x!==o.value)">{{o.label}} ×</button><button v-if="status" @click="status=''">{{fmt(status)}} ×</button><button v-if="minCargo!==''" @click="minCargo=''">Груз ≥ {{minCargo}} ×</button><button v-if="maxCrew!==''" @click="maxCrew=''">Экипаж ≤ {{maxCrew}} ×</button><button v-if="maxPrice!==''" @click="maxPrice=''">Цена ≤ {{compact(maxPrice)}} ×</button><button v-if="kind!=='all'" @click="kind='all'">{{kind==='ship'?'Корабли':'Наземная'}} ×</button><button v-if="countRules(root)" @click="builder=true">Воронка: {{countRules(root)}} условий ↗</button></div>
    <div class="results-toolbar"><p aria-live="polite"><b>{{results.length}}</b> <span>из {{ships.length}} моделей</span></p><div class="results-controls"><button class="text-button export-button" @click="exportResults">↓ CSV</button><label class="sort-label"><span>Сортировка</span><select v-model="sort" aria-label="Сортировка"><option value="name">Название</option><option v-for="f in fields.filter(x=>x.type==='number'&&(fieldVisible(x,scope)||x.key===sort))" :value="f.key" :key="f.key">{{f.label}} · {{f.group}}</option></select></label><button class="icon-button" :aria-label="direction==='asc'?'По убыванию':'По возрастанию'" @click="direction=direction==='asc'?'desc':'asc'">{{direction==='asc'?'↑':'↓'}}</button><div class="view-toggle"><button :class="{selected:view==='grid'}" @click="view='grid'" aria-label="Карточки">▦</button><button :class="{selected:view==='table'}" @click="view='table'" aria-label="Таблица">☰</button></div></div></div>
    <div v-if="!results.length" class="empty-state"><div>⌕</div><h3>Здесь пока пустое пространство</h3><p>Ни один корабль не подходит под эти условия.<br>Ослабьте ограничения или включите неизвестные значения в конструкторе.</p><button class="primary-button" @click="reset">Сбросить фильтры</button></div>
    <TransitionGroup v-else-if="view==='grid'" name="cards" tag="div" class="ship-grid" appear><article v-for="(s,index) in visible" :key="s.id" class="ship-card" :style="{'--reveal-delay':Math.min(index,6)*25+'ms'}" :class="{chosen:selected.includes(s.id)}"><div class="ship-visual"><button class="ship-photo-button" :aria-label="'Открыть '+s.name" @click="showDetail(s)"><img v-if="s.image" :src="imageUrl(s.image)" :alt="s.name" loading="lazy" @error="$event.target.style.opacity='0'"><span class="ship-fallback">◈</span><ShipRoleTags :ship="s" :patch="catalog.pvp?.patch" /></button><span class="status-pill" :title="statusNote(s)" :class="{ready:s.values.status==='flight-ready'}"><i></i>{{fmt(s.values.status)}}</span><button class="compare-toggle" :class="{chosen:selected.includes(s.id)}" :aria-label="(selected.includes(s.id)?'Убрать ':'Сравнить ')+s.name" :aria-pressed="selected.includes(s.id)" @click="toggle(s)">{{selected.includes(s.id)?'В сравнении':'В сравнение'}}</button></div><div class="ship-body"><span v-if="s.values.added" class="added-badge">ДОПОЛНЕНО · RSI</span><div class="ship-maker">{{s.values.manufacturer}}</div><button class="ship-title" @click="showDetail(s)">{{s.name}} <span>↗</span></button><p class="ship-focus">{{s.values.focus||'Назначение не указано'}}</p><div class="ship-specs"><div><span>Груз / SCU</span><b>{{fmt(s.values.cargo)}}</b></div><div><span>Длина / м</span><b>{{fmt(s.values.length)}}</b></div></div><div class="card-crew"><span class="card-stat-title">Экипаж · чел.</span><CrewValue :values="s.values" :format="fmt" /></div><CardDeflection :values="s.values" :format="fmt" /><p v-if="acquisition.length" class="acquisition-match">{{acquisitionNote(acquisitionById[s.id],acquisition)}}</p><div class="ship-footer"><span>{{compact(s.values.price)}} <small>aUEC</small></span><button @click="showDetail(s)">Характеристики <span>→</span></button></div></div></article></TransitionGroup>
    <div v-else class="table-scroll"><table class="catalog-table"><thead><tr><th></th><th>Корабль</th><th>Статус</th><th>Груз, SCU</th><th>Экипаж</th><th>SCM, м/с</th><th>Цена, aUEC</th></tr></thead><tbody><tr v-for="s in visible" :key="s.id"><td><input type="checkbox" :checked="selected.includes(s.id)" @change="toggle(s)" :aria-label="'Сравнить '+s.name"></td><td><button @click="showDetail(s)">{{s.name}}</button><small>{{s.values.manufacturer}}</small></td><td>{{fmt(s.values.status)}}</td><td>{{fmt(s.values.cargo)}}</td><td><CrewValue :values="s.values" :format="fmt" /></td><td>{{fmt(s.values.scm)}}</td><td>{{fmt(s.values.price)}}</td></tr></tbody></table></div>
    <div class="pagination"><span>{{results.length?((page-1)*pageSize+1):0}}–{{Math.min(page*pageSize,results.length)}} из {{results.length}}</span><div><button @click="page=1" :disabled="page===1" aria-label="Первая страница">«</button><button @click="page--" :disabled="page===1" aria-label="Предыдущая страница">←</button><span>{{page}} / {{totalPages}}</span><button @click="page++" :disabled="page===totalPages" aria-label="Следующая страница">→</button><button @click="page=totalPages" :disabled="page===totalPages" aria-label="Последняя страница">»</button></div></div>
   </section></main>
   <footer class="site-footer"><a class="brand" :href="appBase">◈ ATLAS</a><p>Независимый каталог Star Citizen. Данные: <a href="https://fleetyards.net" target="_blank" rel="noreferrer">FleetYards</a> и <a href="https://robertsspaceindustries.com/ship-matrix" target="_blank" rel="noreferrer">RSI</a>.<br>Изображения и Star Citizen принадлежат Cloud Imperium. Неофициальный некоммерческий проект.</p><button class="text-button" @click="modal='sources'">О данных ↗</button></footer>
   <Transition name="tray"><div v-if="selected.length" class="compare-tray"><div class="tray-label"><span class="orange-dot"></span><b>{{selected.length}}</b> в сравнении</div><div class="tray-ships"><button v-for="s in selectedShips" :key="s.id" @click="toggle(s)">{{s.name}} <span>×</span></button></div><button class="text-button clear-compare" @click="selected=[]">Очистить</button><button class="primary-button" @click="modal='compare'">Сравнить <span>↗</span></button></div></Transition>
  </template>
  <Transition name="modal"><div v-if="builder" class="overlay" @click.self="builder=false"><section class="dialog builder-dialog" role="dialog" aria-modal="true" aria-labelledby="builder-title"><div class="dialog-head"><div><div class="eyebrow">КОНСТРУКТОР / FUNNEL</div><h2 id="builder-title">Любые условия. Один выбор.</h2></div><button class="icon-button" @click="builder=false" aria-label="Закрыть конструктор">×</button></div><p class="dialog-intro">Соединяйте характеристики через И, ИЛИ и НЕ. Вложенные группы позволяют описать сложный выбор. Быстрые фильтры применяются вместе с воронкой.</p><div class="funnel-preview"><span>Весь каталог <b>{{ships.length}}</b></span><i>→</i><span>Быстрые фильтры <b>{{quickResults.length}}</b></span><i>→</i><span class="highlight">Ваша выборка <b>{{results.length}}</b></span></div><div class="builder-scope"><FieldScope v-model="scope" /><span class="muted small">Выбранные условия доступны при любом уровне.</span></div><RuleGroup :group="root" :fields="builderFields" :show-paths="scope==='technical'" /><details class="help-note"><summary>Как работают неизвестные значения и списки</summary><p>«Исключить» убирает корабли без значения; «включить» пропускает их; «только неизвестные» отбирает только пропуски. Ноль и «Нет» — известные значения. В списках по умолчанию достаточно одного совпадения, отрицательные операторы требуют отсутствия совпадений. Условия по разным полям списка проверяются независимо и могут относиться к разным элементам. Для «одно из» разделяйте значения символом |. Пустая группа не ограничивает результат.</p></details><div class="dialog-actions"><button class="outline-button" @click="download('atlas-funnel.json',JSON.stringify(snapshot(),null,2))">↓ Экспорт JSON</button><label class="outline-button file-button">↑ Импорт<input type="file" accept=".json,application/json" @change="importPreset"></label><button class="outline-button" @click="share">Ссылка</button><button class="outline-button" @click="builder=false;modal='saved'">Сохранить</button><button class="primary-button" @click="builder=false">Показать {{results.length}} моделей →</button></div></section></div></Transition>
  <Transition name="modal"><div v-if="modal" class="overlay" @click.self="modal=''"><section class="dialog" :class="{'wide-dialog':modal==='compare','detail-dialog':modal==='detail'}" role="dialog" aria-modal="true" :aria-label="modal==='compare'?'Сравнение кораблей':'Информация'"><button class="dialog-close icon-button" @click="modal=''" aria-label="Закрыть окно">×</button>
   <template v-if="modal==='compare'"><div class="eyebrow">COMPARE / SIDE BY SIDE</div><h2>Разница — в деталях.</h2><p class="dialog-intro">{{selected.length}} моделей в сравнении. {{comparisonMode==='specs'?'Различающиеся значения выделены цветом. Прочерк означает отсутствие данных.':'Сопоставьте условия боя и защиту от одного и того же оружия.'}}</p><nav class="comparison-mode" aria-label="Режим сравнения"><button :class="{active:comparisonMode==='specs'}" :aria-pressed="comparisonMode==='specs'" @click="comparisonMode='specs'">Характеристики</button><button :class="{active:comparisonMode==='pvp'}" :aria-pressed="comparisonMode==='pvp'" @click="comparisonMode='pvp'">PvP и броня</button></nav><KeepAlive><PvpComparison v-if="comparisonMode==='pvp'&&selectedShips.length>=2" :ships="selectedShips" :data="catalog.pvp" /></KeepAlive><p v-if="comparisonMode==='pvp'&&selectedShips.length<2" class="empty-state">Добавьте хотя бы два корабля для сравнения.</p><template v-if="comparisonMode==='specs'"><div class="compare-controls"><label class="check-row"><input type="checkbox" v-model="diffOnly">Только различия</label><span class="comparison-selection-count">Выбрано {{comparisonKeys.length}} · показано {{compareFields.length}}</span><input type="search" v-model="compareSearch" placeholder="Найти характеристику…" aria-label="Поиск в сравнении"><button class="text-button" @click="download('atlas-comparison.csv',csv([['Характеристика',...selectedShips.map(s=>s.name)],...compareFields.map(f=>[f.label+' ['+f.key+']',...selectedShips.map(s=>fmt(s.values[f.key]))])]),'text/csv;charset=utf-8')">↓ CSV</button></div><ComparisonFieldPicker v-model="comparisonKeys" :fields="fields" :defaults="comparisonDefaults" /><div v-if="selected.length<2" class="empty-state"><div>⇄</div><h3>Добавьте хотя бы два корабля</h3><p>Нажмите «В сравнение» на карточках в каталоге.</p><button class="primary-button" @click="modal=''">Вернуться в каталог</button></div><div v-else class="comparison-scroll"><table class="comparison-table"><thead><tr><th>Характеристика <small>{{compareFields.length}} строк</small></th><th v-for="s in selectedShips" :key="s.id"><img v-if="s.image" :src="imageUrl(s.image)" :alt="s.name"><div>{{s.name}}<button class="icon-button" :aria-label="'Убрать '+s.name" @click="toggle(s)">×</button></div><small>{{s.values.manufacturer}}</small></th></tr></thead><tbody><tr v-for="f in compareFields" :key="f.key" :class="{different:different(selectedShips,f.key)}"><th>{{f.label}} <span v-if="f.unit">· {{f.unit}}</span><small>{{f.group}}<template v-if="scope==='technical'"><br>{{f.key.includes('.')?f.key:''}}</template></small></th><td v-for="s in selectedShips" :key="s.id" :class="{missing:isMissing(s.values[f.key])}"><FieldValue :value="s.values[f.key]" :format="fmt" /><small>{{sourceName(s,f.key)}}</small></td></tr><tr v-if="!compareFields.length"><td :colspan="selectedShips.length+1">{{!comparisonKeys.length?'Выберите характеристики кнопкой выше.':compareSearch?'По этому поиску нет строк. Измените запрос или отключите «Только различия».':diffOnly?'Выбранные характеристики совпадают. Отключите «Только различия», чтобы увидеть их значения.':'Нет строк для отображения.'}}</td></tr></tbody></table></div></template></template>
   <template v-else-if="modal==='detail'&&detail"><div class="detail-hero"><img v-if="detail.image" :src="imageUrl(detail.image)" :alt="detail.name"><div><div class="eyebrow">{{detail.values.manufacturer}}</div><h2>{{detail.name}}</h2><span class="status-pill" :title="statusNote(detail)" :class="{ready:detail.values.status==='flight-ready'}">{{fmt(detail.values.status)}}</span></div></div><div class="detail-content"><div class="detail-actions"><button class="primary-button" @click="toggle(detail)">{{selected.includes(detail.id)?'✓ В сравнении':'＋ Добавить в сравнение'}}</button><a v-if="detail.fleetUrl" :href="detail.fleetUrl" target="_blank" rel="noreferrer">FleetYards ↗</a><a v-if="detail.rsiUrl" :href="detail.rsiUrl" target="_blank" rel="noreferrer">RSI ↗</a></div><ShipRoleTags :ship="detail" :patch="catalog.pvp?.patch" expanded /><details v-if="detail.description" class="ship-description"><summary>О корабле</summary><p class="description">{{detail.description}}</p></details><ShipSpecs :key="detail.id" :ship="detail" :fields="fields" :format="fmt" :source-name="sourceName" :pvp="catalog.pvp" @add="addField" /></div></template>
   <template v-else-if="modal==='fields'"><div class="eyebrow">ХАРАКТЕРИСТИКИ / ПОИСК</div><h2>Найдите нужный параметр</h2><p class="dialog-intro">Выберите группу или начните вводить название. ＋ добавит условие в воронку. Справа — число моделей с известным значением.</p><FieldExplorer :fields="fields" :total="ships.length" @add="addField" /></template>
   <template v-else-if="modal==='saved'"><div class="eyebrow">YOUR SHORTLISTS</div><h2>Мои воронки</h2><p class="dialog-intro">Сохраняйте поиск вместе с условиями и выбранными кораблями. Воронки хранятся в этом браузере; JSON позволяет перенести их на другое устройство.</p><form class="save-form" @submit.prevent="savePreset"><input v-model="presetName" placeholder="Название воронки" aria-label="Название воронки" maxlength="100" required><button class="primary-button" type="submit">Сохранить текущую</button></form><div v-if="!saved.length" class="empty-state"><h3>Ваши лучшие находки будут здесь</h3><p>Настройте условия и сохраните первую воронку.</p></div><div class="saved-row" v-for="p in saved" :key="p.id"><div><b>{{p.name}}</b><small>{{countRules(p.data.root)}} условий конструктора</small></div><button class="outline-button" @click="restore(p.data);modal=''">Открыть</button><button class="icon-button" :aria-label="'Удалить воронку '+p.name" @click="deletePreset(p.id)">×</button></div><div class="dialog-actions"><button class="outline-button" @click="download('atlas-funnel.json',JSON.stringify(snapshot(),null,2))">↓ Экспорт текущей</button><label class="outline-button file-button">↑ Импорт JSON<input type="file" accept=".json" @change="importPreset"></label></div></template>
   <template v-else-if="modal==='sources'"><div class="eyebrow">DATA / PROVENANCE</div><h2>Открытые данные.<br>Прозрачные источники.</h2><p class="dialog-intro">Снимок от {{snapshotDate}}. {{catalog.meta.fleetCount}} моделей FleetYards + {{catalog.meta.added.length}} отсутствующих записей из официальной матрицы RSI.</p><div class="source-card"><h3>FleetYards</h3><p>Основные характеристики, габариты, полёт, корпус, баки, грузовые отсеки, магазины и цены. В приоритете для общих полей.</p><a href="https://fleetyards.net/ships/" target="_blank" rel="noreferrer">Открыть источник ↗</a></div><div class="source-card"><h3>RSI Ship Matrix</h3><p>Официальная матрица: модели, состав компонентов, экипаж и дополнительные издания. Значения могут отставать от игры; поля RSI сохранены отдельно и явно подписаны.</p><a href="https://robertsspaceindustries.com/ship-matrix" target="_blank" rel="noreferrer">Открыть источник ↗</a></div><h3>Добавлено из RSI</h3><p>{{catalog.meta.added.join(' · ')}}</p><div class="help-note">{{catalog.meta.note}} Это не обещание наличия всех возможных игровых параметров: в подборе оставлены поля с различающимися значениями минимум у четырёх моделей; дубликаты объединены. Автоматическое фоновое обновление не включено.</div></template>
   <template v-else-if="modal==='share'"><h2>Ссылка на воронку</h2><textarea :value="shareLink" readonly aria-label="Ссылка на воронку" @focus="$event.target.select()"></textarea></template>
  </section></div></Transition>
  <Transition name="toast"><div v-if="notice" class="toast" role="status">{{notice}}</div></Transition>
 </div>
</template>




<style>
.acquisition-match{font-size:10px;line-height:1.6;color:var(--accent);margin:0 0 12px;overflow-wrap:anywhere}
</style>
